parameters.functionCode:
let inputUrl = $json.url || '';
let asin = $json.asin || null;

if (inputUrl.includes('amzn.to')) {
  return {
    shortlink: inputUrl,
    needsRedirect: true
  };
}

if (!asin && inputUrl.includes('/dp/')) {
  asin = inputUrl.split('/dp/')[1]?.split('/')[0];
}

if (!asin) {
  throw new Error("ASIN no detectado. Asegúrate de enviar un ASIN válido o una URL completa de Amazon.");
}

return {
  asin,
  url: `https://www.amazon.es/dp/${asin}?tag=semillasdet02-21`,
  resolved: true
};

let resolvedUrl = $json.responseUrl || '';
let asin = null;

if (resolvedUrl.includes('/dp/')) {
  asin = resolvedUrl.split('/dp/')[1]?.split('/')[0];
}

if (!asin) {
  throw new Error("No se pudo extraer ASIN desde el shortlink resuelto.");
}

return {
  asin,
  url: `https://www.amazon.es/dp/${asin}?tag=semillasdet02-21`,
  resolved: true
};

